            .action-hint strong{color:#ff6b35}
            .clear-btn{width:100%;background:#f8f9fa;color:#666;border:1px solid #ddd;border-radius:8px;padding:12px;font-size:14px;cursor:pointer;transition:all 0.2s;margin-top:32px}
            .clear-btn:hover{background:#ffefeb;color:#ff6b35;border-color:#ff6b35}
