var v = String(source.getVariable()).split(',');
var idx = parseInt(v[0]) || 0;
var tabs = ['小说', '听书', '漫画', '短剧'];
var tab = tabs[idx] || '小说';
var channels = ['男频', '女频'];
var ch = channels[parseInt(v[3]) || 0] || '男频';
var url = 'https://fq.taijiwang.top/api/discover/style?tab=' + encodeURIComponent(tab) + '&source_type=' + encodeURIComponent(ch);
var d = JSON.parse(java.ajax(url));
var styles = d.data || [];
var arr = [];
for (var i = 0; i < styles.length; i++) {
  var it = styles[i];
  var t = String(it.title).replace(/[°・\*.☆]/g, '').trim();
  if (it.url) {
    arr.push({title: t, url: it.url});
  } else {
    arr.push({title: t, url: '', style: {layout_flexGrow: 1, layout_flexBasisPercent: 1, background: '#37474f', borderRadius: '6px'}});
  }
}
JSON.stringify(arr);

