source.loginUrl:
A = () => {
    let v = String(this.source.getVariable()).split(",");
    let x = parseInt(v[0]) || 0;
    let names = ["小说", "听书", "漫画", "短剧"];
    let icons = ["📖", "🎧", "🖼", "🎬"];
    let chs = ["男频", "女频"];
    let ch = chs[parseInt(v[3]) || 0] || '男频';
    let cmt = v[1] == 'off' ? '关闭' : '开启';
    let nl = String.fromCharCode(10);
    java.toast('━━━━━━━━━━━' + nl +
        icons[x] + ' 当前模式' + nl +
        names[x] + nl +
        '━━━━━━━━━━━' + nl +
        '👥 频道' + nl +
        ch + nl +
        '━━━━━━━━━━━' + nl +
        '💬 评论开关' + nl +
        cmt + nl +
        '━━━━━━━━━━━');
}

B = (x) => {
    let v = String(this.source.getVariable()).split(",");
    v[0] = x;
    this.source.setVariable(v.join(","));
    let names = ["小说", "听书", "漫画", "短剧"];
    java.toast('已切换到：' + names[x]);
}

C = () => {
    java.startBrowser('https://fq.taijiwang.top', '');
}

D = () => {
    let v = String(this.source.getVariable()).split(",");
    v[1] = (v[1] == 'off') ? 'on' : 'off';
    this.source.setVariable(v.join(","));
    java.toast('💬 评论已' + (v[1] == 'on' ? '开启' : '关闭'));
}

E = (x) => {
    let v = String(this.source.getVariable()).split(",");
    v[3] = x;
    this.source.setVariable(v.join(","));
    let names = ["男频", "女频"];
    java.toast('已切换到：' + names[x] + '（发现页联动）');
}

